diff --git a/components/canvas/actions-info/use-ai-edit-form.ts b/components/canvas/actions-info/use-ai-edit-form.ts
new file mode 100644
index 0000000..168e885
--- /dev/null
+++ b/components/canvas/actions-info/use-ai-edit-form.ts
@@ -0,0 +1,138 @@
+'use client';
+
+import { useCallback } from 'react';
+import { useTranslations } from 'next-intl';
+import mixpanel from 'mixpanel-browser';
+import { toast } from 'sonner';
+
+import {
+  convertToBase64,
+  getImageDimensionsFromBase64
+} from '@/utils/client/image';
+import { useHistoryState } from '@/hooks/use-history-state';
+import { useCanvasGenerationHandler } from '@/hooks/use-canvas-generation-handler';
+import { imageGenGemini, imageGenOpenAI } from '@/lib/client/image-generation';
+import {
+  GeminiImageGenerationData,
+  ImageGenerationMode,
+  OpenAIImageGenerationData
+} from '@/types/image-generation';
+import useIsBanned from '@/hooks/use-is-banned';
+
+import { ImageObject, isImageObject } from '../types';
+import { executeRequestWithRetries } from '../util';
+
+export interface UseAIEditFormProps {
+  image: ImageObject | null;
+  onUpdateImage: (image: ImageObject) => void;
+  onSuccess?: () => void;
+}
+
+export function useAIEditForm({
+  image,
+  onUpdateImage,
+  onSuccess
+}: UseAIEditFormProps) {
+  const t = useTranslations('Canvas.actionsInfo');
+  const tError = useTranslations('errors');
+  const { isBanned, releaseAt } = useIsBanned();
+  const { generateOnCanvas, isGenerating } = useCanvasGenerationHandler();
+  const { commitTempCanvasObjects } = useHistoryState();
+
+  const handleGenerate = useCallback(
+    async (prompt: string, selectedModel: 'gemini' | 'openai') => {
+      if (!image || !isImageObject(image) || !prompt.trim()) return;
+      if (isBanned) {
+        toast.error(tError('userBanned', { releaseAt }));
+        return;
+      }
+
+      const imageId = Array.isArray(image.imageIds)
+        ? image.imageIds[image.currentIndex ?? 0]
+        : image.imageIds;
+
+      let base64Src: string | undefined;
+      if (!imageId) {
+        const imageSrc = Array.isArray(image.src)
+          ? image.src[image.currentIndex ?? 0]
+          : image.src;
+        base64Src = await convertToBase64(imageSrc);
+      }
+
+      await generateOnCanvas({
+        numberOfImages: 1,
+        objectId: image.id,
+        action: 'ai-edit',
+        imageObject: image,
+        generationRequest: async () => {
+          const result = await executeRequestWithRetries(
+            async () => {
+              if (selectedModel === 'openai') {
+                const params: OpenAIImageGenerationData = {
+                  prompt,
+                  type: ImageGenerationMode.aiEdit,
+                  size: 'auto' as const
+                };
+                if (imageId) {
+                  params.inputImages = [{ id: imageId }];
+                } else if (base64Src) {
+                  params.inputImageBase64 = base64Src;
+                }
+                return await imageGenOpenAI(params);
+              }
+              const params: GeminiImageGenerationData = {
+                prompt,
+                type: ImageGenerationMode.aiEdit
+              };
+              if (imageId) {
+                params.inputImages = [{ id: imageId }];
+              } else if (base64Src) {
+                params.inputImageBase64 = base64Src;
+              }
+              return await imageGenGemini(params);
+            },
+            t
+          );
+          return result;
+        },
+        onGenerationComplete: async ({ imageGenerationId, imageSrc }) => {
+          if (!imageSrc?.length) {
+            throw new Error('No image returned');
+          }
+
+          const { width, height } = await getImageDimensionsFromBase64(
+            imageSrc[0]
+          );
+
+          onUpdateImage({
+            ...image,
+            src: imageSrc[0],
+            width,
+            height,
+            imageGenerationId
+          });
+
+          commitTempCanvasObjects({
+            type: 'Generated Image',
+            objectId: image.id
+          });
+          mixpanel.track('[Canvas] AI Edited', { model: selectedModel });
+          onSuccess?.();
+        }
+      });
+    },
+    [
+      image,
+      onUpdateImage,
+      onSuccess,
+      isBanned,
+      releaseAt,
+      t,
+      tError,
+      generateOnCanvas,
+      commitTempCanvasObjects
+    ]
+  );
+
+  return { handleGenerate, isGenerating };
+}
