+    'gemini'
+  );
+
+  const getTargetObject = useCallback((): ImageObject | undefined => {
+    if (!image || !isImageObject(image)) return undefined;
+    return image;
+  }, [image]);
+
+  const { handleGenerate, isGenerating } = useAIEditForm({
+    image,
+    onUpdateImage,
+    onSuccess: onClose
+  });
+
+  const { updatePosition, updatePositionForObject } =
+    useFloatingElementPosition({
+      containerRef,
+      getTargetObject
+    });
+
+  const position = useCanvasTransformStore((state) => state.position);
+  const scale = useCanvasTransformStore((state) => state.scale);
+  const draggingImageId = useImageDragStore((state) => state.draggingImageId);
+  const dragPosition = useImageDragStore((state) => state.dragPosition);
+  const dragDimensions = useImageDragStore((state) => state.dragDimensions);
+  const dragScale = useImageDragStore((state) => state.dragScale);
+
+  const isDraggingThisImage =
+    image && draggingImageId === image.id;
+
+  useEffect(() => {
+    if (image && open) {
+      updatePosition();
+    }
+  }, [image, open, updatePosition]);
+
+  useEffect(() => {
+    if (image && open) {
+      updatePosition();
+    }
+  }, [position.x, position.y, scale, image, open, updatePosition]);
+
+  useEffect(() => {
+    if (image && !isDraggingThisImage) {
+      updatePositionForObject(image);
+    }
+  }, [
+    image?.position.x,
+    image?.position.y,
+    image?.width,
+    image?.height,
+    image?.scaleX,
+    image?.scaleY,
+    image,
+    isDraggingThisImage,
+    updatePositionForObject
+  ]);
+
+  useEffect(() => {
+    if (isDraggingThisImage && image && dragPosition && dragDimensions) {
+      const tempImage: ImageObject = {
+        ...image,
+        position: dragPosition,
+        width: dragDimensions.width,
+        height: dragDimensions.height,
+        scaleX: dragScale?.scaleX ?? image.scaleX ?? 1,
+        scaleY: dragScale?.scaleY ?? image.scaleY ?? 1
+      };
+      updatePositionForObject(tempImage);
+    }
+  }, [
+    isDraggingThisImage,
+    dragPosition,
+    dragDimensions,
+    dragScale,
+    image,
+    updatePositionForObject
+  ]);
+
+  const handleSubmit = useCallback(() => {
+    handleGenerate(prompt, selectedModel);
+  }, [handleGenerate, prompt, selectedModel]);
+
+  // Only show AI Edit form for real images; placeholder uses "new image" form (FloatingTextareaContainer)
+  const visible =
+    open && !!image && !isPlaceholderImage(image);
+
+  return (
+    <FloatingTextarea
+      ref={containerRef}
+      variant="ai-edit"
+      value={prompt}
+      onChange={setPrompt}
+      onSubmit={handleSubmit}
+      visible={visible}
+      width={TEXTAREA_WIDTH}
+      isGenerating={isGenerating}
+      selectedAiEditModel={selectedModel}
+      onAiEditModelChange={setSelectedModel}
+    />
+  );
+}
