diff --git a/components/canvas/floating/QuickActionButton.tsx b/components/canvas/floating/QuickActionButton.tsx
new file mode 100644
index 0000000..4c947e5
--- /dev/null
+++ b/components/canvas/floating/QuickActionButton.tsx
@@ -0,0 +1,78 @@
+'use client';
+
+import { forwardRef, type ButtonHTMLAttributes } from 'react';
+import { cn } from '@/lib/utils';
+import Spinner from '@/components/spinner';
+
+export type QuickActionButtonVariant = 'default' | 'active' | 'danger';
+
+export interface QuickActionButtonProps
+  extends ButtonHTMLAttributes<HTMLButtonElement> {
+  /** 視覺變體：default、active（主色高亮）、danger（刪除紅） */
+  variant?: QuickActionButtonVariant;
+  /** 是否為啟用/選中狀態（搭配 variant="active" 使用） */
+  isActive?: boolean;
+  /** 是否顯示載入中（顯示 Spinner） */
+  isLoading?: boolean;
+  /** 按鈕文字，顯示在 icon 後方 */
+  label?: React.ReactNode;
+}
+
+const baseStyles =
+  'p-1.5 rounded-md transition-colors min-h-[28px] flex items-center justify-center gap-1.5 disabled:opacity-30 disabled:cursor-not-allowed focus:outline-none focus:ring-0';
+
+function getVariantClassName(
+  variant: QuickActionButtonVariant,
+  isActive: boolean
+): string {
+  if (variant === 'active' && isActive)
+    return 'bg-blue-100 text-blue-600 hover:bg-blue-100';
+  if (variant === 'danger')
+    return 'hover:bg-red-50 hover:text-red-700 text-red-600';
+  return 'hover:bg-gray-100 hover:text-blue-600';
+}
+
+export const QuickActionButton = forwardRef<
+  HTMLButtonElement,
+  QuickActionButtonProps
+>(function QuickActionButton(
+  {
+    variant = 'default',
+    isActive = false,
+    isLoading = false,
+    disabled,
+    className,
+    children,
+    label,
+    ...props
+  },
+  ref
+) {
+  return (
+    <button
+      ref={ref}
+      type="button"
+      disabled={disabled ?? isLoading}
+      className={cn(
+        baseStyles,
+        !label && 'min-w-[28px]',
+        getVariantClassName(variant, isActive),
+        className
+      )}
+      {...props}
+    >
+      {isLoading ? (
+        <Spinner className="h-4 w-4" />
+      ) : (
+        <>
+          {children}
+          {label != null && (
+            <span className="text-xs font-medium whitespace-nowrap">
+              {label}
+            </span>
+          )}
+        </>
+      )}
+    </button>
+  );
+});
